import os
from google.cloud import kms_v1

def encrypt_with_managed_key(plaintext: bytes, key_name: str) -> bytes:
    client = kms_v1.KeyManagementServiceClient()
    response = client.encrypt(
        request={
            "name": key_name,
            "plaintext": plaintext
        }
    )
    return response.ciphertext
